style.css:
/* Global Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Body Styling */
body {
    font-family: 'Roboto', Arial, sans-serif;
    background: linear-gradient(135deg, #f5f7fa, #c3cfe2);
    color: #333;
    padding: 20px;
}

/* Header Styling */
header {
    background: #ff8a65;
    color: white;
    padding: 15px;
    text-align: center;
    font-size: 1.5rem;
    font-weight: bold;
    box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.1);
}

/* Navigation Bar Styling */
nav {
    margin: 20px auto;
    display: flex;
    justify-content: space-around;
    padding: 10px;
    background: #ffccbc;
    border-radius: 8px;
    box-shadow: 0px 2px 5px rgba(0, 0, 0, 0.1);
}

nav a {
    color: #333;
    text-decoration: none;
    font-size: 1rem;
    padding: 10px 15px;
    transition: background-color 0.3s ease;
    border-radius: 5px;
}

nav a:hover {
    background-color: #ff8a65;
    color: white;
}

/* Main Content Styling */
main {
    margin: 20px auto;
    padding: 20px;
    background: white;
    border-radius: 12px;
    box-shadow: 0px 10px 20px rgba(0, 0, 0, 0.1);
    max-width: 800px;
    line-height: 1.6;
}

main h1, main h2 {
    color: #ff7043;
}

main p {
    margin: 10px 0;
    font-size: 1rem;
}

/* Form Styling */
form {
    display: flex;
    flex-direction: column;
    gap: 15px;
    margin-top: 20px;
}

form input[type="text"], form input[type="password"] {
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 8px;
    font-size: 1rem;
}

form input:focus {
    outline: none;
    border-color: #ff7043;
    box-shadow: 0px 0px 8px rgba(255, 112, 67, 0.5);
}

form button {
    padding: 12px;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    background: #ff8a65;
    color: white;
    cursor: pointer;
    transition: background 0.3s ease;
}

form button:hover {
    background: #e64a19;
}

/* Footer Styling */
footer {
    margin-top: 20px;
    padding: 15px;
    background: #ff8a65;
    color: white;
    text-align: center;
    font-size: 0.9rem;
    border-radius: 8px;
}
